def asteroid_collision(asteroids):
    stack = []
    for rock in asteroids:
        alive = True
        while alive and stack and stack[-1] > 0 and rock < 0:
            if stack[-1] < -rock:
                stack.pop()          # top loses, attacker continues
            elif stack[-1] == -rock:
                stack.pop()          # mutual annihilation
                alive = False
            else:
                alive = False        # attacker loses
        if alive:
            stack.append(rock)
    return stack

