using namespace std;

vector<int> asteroidCollision(vector<int>& asteroids) {
    vector<int> st;  // doubles as the stack
    for (int rock : asteroids) {
        bool alive = true;
        while (alive && !st.empty() && st.back() > 0 && rock < 0) {
            if (st.back() < -rock) { st.pop_back(); }
            else if (st.back() == -rock) { st.pop_back(); alive = false; }
            else { alive = false; }
        }
        if (alive) st.push_back(rock);
    }
    return st;
}

