import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public int[] asteroidCollision(int[] asteroids) {
        Deque<Integer> stack = new ArrayDeque<>();
        for (int rock : asteroids) {
            boolean alive = true;
            while (alive && !stack.isEmpty() && stack.peek() > 0 && rock < 0) {
                if (stack.peek() < -rock) stack.pop();
                else if (stack.peek() == -rock) { stack.pop(); alive = false; }
                else alive = false;
            }
            if (alive) stack.push(rock);
        }
        int[] ans = new int[stack.size()];
        for (int i = ans.length - 1; i >= 0; --i) ans[i] = stack.pop();
        return ans;
    }
}
